referenceSolutions.javascript:
export function productExceptSelf(values) {
  const result = Array(values.length).fill(1);
  let prefix = 1, suffix = 1;
  for (let i = 0; i < values.length; i++) {
    result[i] = prefix;
    prefix *= values[i];
  }
  for (let i = values.length - 1; i >= 0; i--) {
    result[i] *= suffix;
    suffix *= values[i];
  }
  return result;
}

